'use client'

import { useId, useState } from 'react'
import type { ReactNode } from 'react'
import './editorial-accordion.css'

export interface EditorialAccordionItem {
  /** A unique, stable identifier within this accordion. */
  id: string
  title: string
  content: ReactNode
}

export interface EditorialAccordionProps {
  items: EditorialAccordionItem[]
  defaultValue?: string
  className?: string
}

export function EditorialAccordion({
  items,
  defaultValue,
  className = '',
}: EditorialAccordionProps) {
  const [openId, setOpenId] = useState<string | undefined>(defaultValue)
  const instanceId = useId()

  return (
    <div className={`ac-editorial-accordion ${className}`.trim()}>
      {items.map((item, index) => {
        const isOpen = item.id === openId
        const buttonId = `${instanceId}-trigger-${index}`
        const panelId = `${instanceId}-panel-${index}`

        return (
          <section className="ac-editorial-accordion-item" data-open={isOpen} key={item.id}>
            <h3 className="ac-editorial-accordion-heading">
              <button
                id={buttonId}
                className="ac-editorial-accordion-trigger"
                type="button"
                aria-expanded={isOpen}
                aria-controls={panelId}
                onClick={() => setOpenId(isOpen ? undefined : item.id)}
              >
                <span className="ac-editorial-accordion-number" aria-hidden="true">
                  {String(index + 1).padStart(2, '0')}
                </span>
                <span className="ac-editorial-accordion-title">{item.title}</span>
                <span className="ac-editorial-accordion-icon" aria-hidden="true" />
              </button>
            </h3>
            <div
              id={panelId}
              className="ac-editorial-accordion-panel"
              role="region"
              aria-labelledby={buttonId}
              hidden={!isOpen}
            >
              <div className="ac-editorial-accordion-content">{item.content}</div>
            </div>
          </section>
        )
      })}
    </div>
  )
}

.ac-editorial-accordion {
  color: var(--ac-accordion-color, inherit);
}

.ac-editorial-accordion-item {
  border-top: 1px solid var(--ac-accordion-border, color-mix(in srgb, currentColor 18%, transparent));
}

.ac-editorial-accordion-item:last-child {
  border-bottom: 1px solid var(--ac-accordion-border, color-mix(in srgb, currentColor 18%, transparent));
}

.ac-editorial-accordion-heading {
  margin: 0;
  font: inherit;
}

.ac-editorial-accordion-trigger {
  display: grid;
  width: 100%;
  grid-template-columns: 2rem 1fr 1.5rem;
  align-items: center;
  gap: 1rem;
  padding: 1.6rem 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ac-editorial-accordion-trigger:focus-visible {
  border-radius: 3px;
  outline: 2px solid var(--ac-focus-color, currentColor);
  outline-offset: 6px;
}

.ac-editorial-accordion-number {
  align-self: start;
  padding-top: 0.35em;
  color: var(--ac-accordion-muted, color-mix(in srgb, currentColor 70%, transparent));
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 0.65rem;
  font-weight: 400;
}

.ac-editorial-accordion-title {
  font-size: clamp(1.3rem, 2.2vw, 2rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.04em;
  transition: color 180ms ease;
}

.ac-editorial-accordion-trigger:hover .ac-editorial-accordion-title,
.ac-editorial-accordion-item[data-open='true'] .ac-editorial-accordion-title {
  color: var(--ac-accordion-accent, inherit);
}

.ac-editorial-accordion-icon {
  position: relative;
  width: 16px;
  height: 16px;
}

.ac-editorial-accordion-icon::before,
.ac-editorial-accordion-icon::after {
  position: absolute;
  top: 7px;
  left: 1px;
  width: 14px;
  height: 1px;
  background: currentColor;
  content: '';
}

.ac-editorial-accordion-icon::after {
  transform: rotate(90deg);
  transition: transform 220ms ease;
}

.ac-editorial-accordion-item[data-open='true'] .ac-editorial-accordion-icon::after {
  transform: rotate(0deg);
}

.ac-editorial-accordion-panel[hidden] {
  display: none;
}

.ac-editorial-accordion-content {
  max-width: 42rem;
  margin: 0 2.5rem 0 3rem;
  padding-bottom: 1.7rem;
  color: var(--ac-accordion-description, color-mix(in srgb, currentColor 80%, transparent));
  font-size: 0.9rem;
  line-height: 1.7;
}

.ac-editorial-accordion-content > :first-child {
  margin-top: 0;
}

.ac-editorial-accordion-content > :last-child {
  margin-bottom: 0;
}

@media (prefers-reduced-motion: reduce) {
  .ac-editorial-accordion-title,
  .ac-editorial-accordion-icon::after {
    transition: none;
  }
}
